SELECT DISTINCT YEAR(written) year,COUNT(*) OVER(PARTITION BY YEAR(written)) paragraphs,PERCENTILE_CONT(.25) WITHIN GROUP(ORDER BY wait_days) OVER(PARTITION BY YEAR(written)) p25,PERCENTILE_CONT(.5) WITHIN GROUP(ORDER BY wait_days) OVER(PARTITION BY YEAR(written)) median,PERCENTILE_CONT(.75) WITHIN GROUP(ORDER BY wait_days) OVER(PARTITION BY YEAR(written)) p75 FROM facts WHERE has_ref AND referenced IS NOT NULL ORDER BY year;
